mapper.select:
SELECT COALESCE(MAX(version_no), 0) FROM test_asset_version
WHERE project_id = #{projectId} AND asset_type = #{assetType} AND asset_id = #{assetId}
FOR UPDATE

mapper.sql:
WHERE d.project_id = #{projectId} AND d.deleted = 0
AND d.parse_status = #{parseStatus}
AND (LOWER(d.original_name) LIKE CONCAT('%', LOWER(#{keyword}), '%') OR LOWER(d.id) LIKE CONCAT('%', LOWER(#{keyword}), '%') OR LOWER(COALESCE(d.summary, '')) LIKE CONCAT('%', LOWER(#{keyword}), '%'))

WHERE v.project_id = #{projectId}
AND v.asset_type = #{assetType}
AND v.asset_id = #{assetId}

    AND (LOWER(v.asset_id) LIKE CONCAT('%', LOWER(#{keyword}), '%')
         OR LOWER(COALESCE(d.original_name, fc.name, task.name, '')) LIKE CONCAT('%', LOWER(#{keyword}), '%'))

WHERE r.project_id = #{projectId}
AND (r.source_asset_type = #{assetType} OR r.target_asset_type = #{assetType})
AND (r.source_asset_id = #{assetId} OR r.target_asset_id = #{assetId})
AND r.relation_type = #{relationType}
AND (LOWER(r.source_asset_id) LIKE CONCAT('%', LOWER(#{keyword}), '%') OR LOWER(r.target_asset_id) LIKE CONCAT('%', LOWER(#{keyword}), '%') OR LOWER(COALESCE(sd.original_name, sfc.name, st.name, '')) LIKE CONCAT('%', LOWER(#{keyword}), '%') OR LOWER(COALESCE(td.original_name, tfc.name, tt.name, '')) LIKE CONCAT('%', LOWER(#{keyword}), '%'))

mapper.select:
SELECT DISTINCT v.id AS versionId, v.asset_id AS documentId, COALESCE(d.original_name, v.asset_id) AS documentName, v.version_no AS versionNo, v.source_version AS sourceVersion, v.content_hash AS contentHash, v.content_snapshot AS contentSnapshot FROM test_asset_relation r JOIN test_asset_version v ON v.id = r.source_version_id AND v.project_id = r.project_id LEFT JOIN ai_source_document d ON d.id = v.asset_id AND d.project_id = v.project_id WHERE r.project_id = #{projectId} AND r.relation_type = 'DERIVED_FROM' AND r.source_asset_type = 'DOCUMENT' AND r.target_asset_type = 'CASE' AND r.target_asset_id IN
#{caseAssetId}
ORDER BY v.version_no DESC, v.id
